contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, bool include, uint256 filler) public {
        // build a small whitelist of at most 2 entries; target included only if include
        require(filler != target);
        address[] memory whitelist = new address[](2);
        if (include) {
            whitelist[0] = target;
            whitelist[1] = filler;
        } else {
            whitelist[0] = filler;
            whitelist[1] = target == address(0x1) ? address(0x2) : address(0x1);
        }

        bool result = c.isWhitelisted(whitelist, target);

        // scan whitelist through the same pure view of it
        bool found = false;
        for (uint256 i = 0; i < whitelist.length; i++) {
            if (whitelist[i] == target) found = true;
        }

        assert(result == found);
    }

    receive() external payable {}
}

